import { useState, useEffect } from 'react';
import ExamInterface from './ExamInterface';
import ResultView    from './ResultView';

const API = 'http://localhost:5000/api';
const getToken = () => localStorage.getItem('examai_token');

const AvailableExams = ({ store, setExamLocked }) => {
  const [exams,         setExams]         = useState([]);
  const [examQCounts,   setExamQCounts]   = useState({});
  const [completedSubs, setCompletedSubs] = useState([]);
  const [results,       setResults]       = useState([]);
  const [loading,       setLoading]       = useState(true);
  const [takingExam,    setTakingExam]    = useState(null);
  const [shuffledQs,    setShuffledQs]    = useState([]);
  const [resultSubId,   setResultSubId]   = useState(null);
  const [now,           setNow]           = useState(Date.now());
  const [search,        setSearch]        = useState('');
  const [filter,        setFilter]        = useState('all');

  useEffect(() => {
    loadAll();
    const t = setInterval(() => setNow(Date.now()), 30000);
    return () => clearInterval(t);
  }, []);

  const apiFetch = async (path) => {
    const res = await fetch(`${API}${path}`, { headers: { Authorization: `Bearer ${getToken()}` } });
    return res.json();
  };

  const loadAll = async () => {
    try {
      setLoading(true);
      const sid = store.getStudentSid();
      const [examsData, subsData] = await Promise.all([
        apiFetch('/exams'),
        apiFetch(`/submissions/student/${sid}`)
      ]);
      const examsArr = Array.isArray(examsData) ? examsData : [];
      const subsArr  = Array.isArray(subsData)  ? subsData  : [];
      setExams(examsArr);
      setCompletedSubs(subsArr);
      const counts = {};
      await Promise.all(examsArr.map(async (e) => {
        const qs = await apiFetch(`/questions/${e.exam_id}`);
        counts[e.exam_id] = Array.isArray(qs) ? qs.length : 0;
      }));
      setExamQCounts(counts);
      const resArr = await Promise.all(
        subsArr.map(s => apiFetch(`/submissions/result/${s.submission_id}`).catch(() => null))
      );
      setResults(resArr.filter(Boolean));
    } catch (e) {
      console.error('AvailableExams load error:', e);
    } finally {
      setLoading(false);
    }
  };

  const getExamStatus = (exam) => {
    const start = exam.start_time ? new Date(exam.start_time).getTime() : null;
    const end   = exam.end_time   ? new Date(exam.end_time).getTime()   : null;
    if (end   && now > end)   return 'expired';
    if (start && now < start) return 'upcoming';
    return 'open';
  };

  const formatDateTime = (iso) => {
    if (!iso) return null;
    return new Date(iso).toLocaleString(undefined, { day:'numeric', month:'short', year:'numeric', hour:'2-digit', minute:'2-digit' });
  };

  const timeUntil = (iso) => {
    const diff = new Date(iso).getTime() - now;
    if (diff <= 0) return null;
    const h = Math.floor(diff / 3600000);
    const m = Math.floor((diff % 3600000) / 60000);
    if (h > 24) return `${Math.floor(h/24)}d ${h%24}h`;
    if (h > 0)  return `${h}h ${m}m`;
    return `${m}m`;
  };

  if (resultSubId) return <ResultView submissionId={resultSubId} store={store} onBack={() => { setResultSubId(null); loadAll(); }} />;

  if (takingExam) {
    return <ExamInterface exam={takingExam} questions={shuffledQs} store={store} onFinish={(sid, wasCheated) => {
      setExamLocked(false); setTakingExam(null); setResultSubId(sid);
      if (wasCheated) store.addToast('Exam terminated: integrity violation.', 'error');
    }} />;
  }

  if (loading) return (
    <div style={{ display:'flex', alignItems:'center', justifyContent:'center', padding:60, gap:12 }}>
      <div className="spinner" style={{ width:24, height:24 }} />
      <span style={{ color:'#6b7280' }}>Loading exams...</span>
    </div>
  );

  const attemptCounts = {};
  completedSubs.forEach(s => { attemptCounts[s.exam_id] = (attemptCounts[s.exam_id]||0)+1; });
  const completedExamIds = new Set(completedSubs.map(s => s.exam_id));

  const openExams     = exams.filter(e => getExamStatus(e) === 'open');
  const upcomingExams = exams.filter(e => getExamStatus(e) === 'upcoming');
  const expiredExams  = exams.filter(e => getExamStatus(e) === 'expired');

  const applyFilters = (arr) => arr.filter(e => {
    const matchSearch = e.title.toLowerCase().includes(search.toLowerCase()) || (e.description||'').toLowerCase().includes(search.toLowerCase());
    if (!matchSearch) return false;
    if (filter === 'all')      return true;
    if (filter === 'open')     return getExamStatus(e) === 'open';
    if (filter === 'upcoming') return getExamStatus(e) === 'upcoming';
    if (filter === 'expired')  return getExamStatus(e) === 'expired';
    if (filter === 'completed')return completedExamIds.has(e.exam_id);
    return true;
  });

  const filteredExams = applyFilters(exams);

  const ExamCard = ({ exam }) => {
    const status      = getExamStatus(exam);
    const qCount      = examQCounts[exam.exam_id] ?? 0;
    const attempts    = attemptCounts[exam.exam_id] || 0;
    const maxAttempts = Number(exam.max_attempts) || 1;
    const canReattempt = exam.allow_reattempt && attempts < maxAttempts;
    const completed   = attempts > 0;
    const allDone     = completed && !canReattempt;
    const sub         = completedSubs.find(s => s.exam_id === exam.exam_id);
    const result      = sub ? results.find(r => r.submission_id === sub.submission_id) : null;
    const isExpired   = status === 'expired';
    const isUpcoming  = status === 'upcoming';

    const handleStart = async () => {
      if (qCount === 0) { store.addToast('This exam has no questions yet.', 'error'); return; }
      await store.loadExamQuestions(exam.exam_id);
      const loaded = store.getExamQuestions(exam.exam_id);
      let questionsToUse = loaded;
      if (loaded.length === 0) {
        const res = await fetch(`${API}/questions/${exam.exam_id}`, { headers: { Authorization: `Bearer ${getToken()}` } });
        questionsToUse = await res.json();
      }
      setShuffledQs(questionsToUse);
      setExamLocked(true);
      setTakingExam(exam);
    };

    const statusColor = allDone ? '#16a34a' : isExpired ? '#dc2626' : isUpcoming ? '#d97706' : '#16a34a';
    const statusBg    = allDone ? '#dcfce7' : isExpired ? '#fee2e2' : isUpcoming ? '#fef3c7' : '#dcfce7';
    const statusLabel = allDone ? 'COMPLETED' : isExpired ? 'EXPIRED' : isUpcoming ? 'UPCOMING' : 'LIVE NOW';

    return (
      <div style={{ background:'#fff', border:`1px solid ${isExpired?'#fecaca':isUpcoming?'#fde68a':allDone?'#bbf7d0':'#e8e8f0'}`, borderRadius:14, padding:20, boxShadow:'0 1px 3px rgba(0,0,0,.06)', transition:'all .2s', position:'relative', overflow:'hidden' }}
        onMouseEnter={e => { e.currentTarget.style.boxShadow='0 4px 16px rgba(0,0,0,.10)'; e.currentTarget.style.transform='translateY(-2px)'; }}
        onMouseLeave={e => { e.currentTarget.style.boxShadow='0 1px 3px rgba(0,0,0,.06)'; e.currentTarget.style.transform='translateY(0)'; }}>

        <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:12 }}>
          <span style={{ background:statusBg, color:statusColor, border:`1px solid ${statusColor}33`, borderRadius:20, padding:'3px 10px', fontSize:10, fontWeight:800, fontFamily:'JetBrains Mono,monospace', letterSpacing:.5 }}>{statusLabel}</span>
          <span style={{ fontSize:11, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace', display:'flex', alignItems:'center', gap:4 }}>🕐 {exam.duration_minutes} min</span>
        </div>

        <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:16, color:'#0f0f1a', marginBottom:4 }}>{exam.title}</div>
        <div style={{ fontSize:10, fontWeight:700, textTransform:'uppercase', letterSpacing:1.5, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace', marginBottom:8 }}>
          {exam.description?.split(' ').slice(0,2).join(' ').toUpperCase() || 'GENERAL'}
        </div>
        <div style={{ fontSize:12, color:'#6b7280', marginBottom:14, lineHeight:1.55, minHeight:36 }}>{exam.description || 'No description.'}</div>

        <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:8, marginBottom:12, padding:10, background:'#f8f8fc', borderRadius:8, border:'1px solid #e8e8f0' }}>
          <div>
            <div style={{ fontSize:9, color:'#9ca3af', textTransform:'uppercase', letterSpacing:1, fontFamily:'JetBrains Mono,monospace', marginBottom:2 }}>QUESTIONS</div>
            <div style={{ fontSize:13, fontWeight:700, color:'#0f0f1a' }}>{qCount} items</div>
          </div>
          <div>
            <div style={{ fontSize:9, color:'#9ca3af', textTransform:'uppercase', letterSpacing:1, fontFamily:'JetBrains Mono,monospace', marginBottom:2 }}>TOTAL MARKS</div>
            <div style={{ fontSize:13, fontWeight:700, color:'#0f0f1a' }}>{exam.total_marks} pts</div>
          </div>
        </div>

        {attempts > 0 && !allDone && (
          <div style={{ marginBottom:10, fontSize:11, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace' }}>
            {attempts}/{maxAttempts} ATTEMPTS USED
          </div>
        )}

        {completed && result && (
          <div style={{ display:'flex', alignItems:'center', gap:8, marginBottom:10 }}>
            <span style={{ fontSize:12, color:'#6b7280' }}>Best: <strong style={{ color:'#0f0f1a' }}>{Number(result.total_score||0).toFixed(0)}/{exam.total_marks}</strong></span>
          </div>
        )}

        {isExpired ? (
          <div style={{ textAlign:'center', padding:'8px', fontSize:13, color:'#dc2626', fontWeight:600 }}>Exam Period Ended</div>
        ) : isUpcoming ? (
          <button className="btn btn-secondary" style={{ width:'100%' }} onClick={() => store.addToast('Reminder set!','success')}>
            📅 Add to Reminder
          </button>
        ) : allDone ? (
          <div style={{ display:'flex', alignItems:'center', gap:8 }}>
            {sub && result && (
              <button className="btn btn-ghost btn-sm" style={{ color:'#7c3aed', fontSize:12, padding:'5px 10px' }} onClick={() => setResultSubId(sub.submission_id)}>
                View AI Feedback ↗
              </button>
            )}
          </div>
        ) : (
          <button onClick={handleStart}
            style={{ width:'100%', padding:'10px', borderRadius:8, border:'none', background:'#7c3aed', color:'white', fontWeight:700, fontSize:13, cursor:'pointer', display:'flex', alignItems:'center', justifyContent:'center', gap:8, transition:'all .15s' }}
            onMouseEnter={e => e.currentTarget.style.background='#6d28d9'}
            onMouseLeave={e => e.currentTarget.style.background='#7c3aed'}>
            ▶ {canReattempt ? `Reattempt (${attempts}/${maxAttempts})` : 'Start Exam Now'}
          </button>
        )}
      </div>
    );
  };

  if (exams.length === 0) return (
    <div>
      <h1 style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:28, color:'#0f0f1a', marginBottom:6 }}>Available Exams</h1>
      <p style={{ color:'#6b7280', fontSize:14, marginBottom:24 }}>Browse your scheduled exams and start active sessions.</p>
      <div className="empty-state"><div className="empty-icon">📭</div><div className="empty-title">No exams available</div><div className="empty-sub">Check back later</div></div>
    </div>
  );

  return (
    <div>
      <h1 style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:28, color:'#0f0f1a', marginBottom:6 }}>Available Exams</h1>
      <p style={{ color:'#6b7280', fontSize:14, marginBottom:22, lineHeight:1.6 }}>Browse your scheduled exams and start active sessions. Browse upcoming schedules and start active sessions.</p>

      {/* Search + Filter Bar */}
      <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:12, padding:'12px 16px', display:'flex', gap:12, alignItems:'center', marginBottom:28, boxShadow:'0 1px 3px rgba(0,0,0,.06)' }}>
        <div style={{ flex:1, position:'relative' }}>
          <span style={{ position:'absolute', left:12, top:'50%', transform:'translateY(-50%)', color:'#9ca3af', fontSize:14 }}>🔍</span>
          <input className="form-input" style={{ paddingLeft:38, border:'none', background:'transparent', boxShadow:'none', padding:'8px 8px 8px 38px' }}
            placeholder="Search by exam title, subject, or keywords..." value={search}
            onChange={e => setSearch(e.target.value)} />
        </div>
        <div style={{ width:1, height:24, background:'#e8e8f0' }} />
        <div style={{ display:'flex', gap:4 }}>
          {[
            { key:'all',       label:'All'       },
            { key:'open',      label:'Live'      },
            { key:'upcoming',  label:'Upcoming'  },
            { key:'completed', label:'Completed' },
            { key:'expired',   label:'Expired'   },
          ].map(f => (
            <button key={f.key} onClick={() => setFilter(f.key)}
              style={{ padding:'5px 14px', borderRadius:20, border:'none', cursor:'pointer', fontSize:12, fontWeight:600, transition:'all .15s',
                background: filter===f.key ? '#7c3aed' : 'transparent',
                color:      filter===f.key ? '#fff' : '#6b7280' }}>
              {f.label}
            </button>
          ))}
        </div>
      </div>

      {filteredExams.length === 0 ? (
        <div className="card"><div className="empty-state" style={{ padding:40 }}>
          <div className="empty-icon">🔍</div>
          <div className="empty-title">No exams match</div>
          <div className="empty-sub">Try a different keyword or filter</div>
        </div></div>
      ) : filter !== 'all' ? (
        <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fill,minmax(300px,1fr))', gap:16 }}>
          {filteredExams.map(e => <ExamCard key={e.exam_id} exam={e} />)}
        </div>
      ) : (
        <>
          {openExams.length > 0 && (
            <div style={{ marginBottom:32 }}>
              <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:16 }}>
                <div>
                  <div style={{ display:'flex', alignItems:'center', gap:8 }}>
                    <div style={{ width:28, height:28, borderRadius:6, background:'#f0fdf4', border:'1px solid #bbf7d0', display:'flex', alignItems:'center', justifyContent:'center', fontSize:13 }}>▶</div>
                    <span style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:18, color:'#0f0f1a' }}>Live Now</span>
                  </div>
                  <div style={{ fontSize:10, color:'#9ca3af', textTransform:'uppercase', letterSpacing:1.5, fontFamily:'JetBrains Mono,monospace', marginTop:2, marginLeft:36 }}>{openExams.length} AVAILABLE MODULES</div>
                </div>
                <button className="btn btn-ghost btn-sm" style={{ color:'#7c3aed' }}>View All →</button>
              </div>
              <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fill,minmax(300px,1fr))', gap:16 }}>
                {openExams.filter(e => applyFilters([e]).length > 0).map(e => <ExamCard key={e.exam_id} exam={e} />)}
              </div>
            </div>
          )}

          {(upcomingExams.length > 0 || expiredExams.length > 0) && (
            <div>
              <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:16 }}>
                <div>
                  <div style={{ display:'flex', alignItems:'center', gap:8 }}>
                    <div style={{ width:28, height:28, borderRadius:6, background:'#ede9fe', border:'1px solid #ddd6fe', display:'flex', alignItems:'center', justifyContent:'center', fontSize:13 }}>▣</div>
                    <span style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:18, color:'#0f0f1a' }}>Other Exams</span>
                  </div>
                  <div style={{ fontSize:10, color:'#9ca3af', textTransform:'uppercase', letterSpacing:1.5, fontFamily:'JetBrains Mono,monospace', marginTop:2, marginLeft:36 }}>{upcomingExams.length + expiredExams.length} MODULES</div>
                </div>
                <button className="btn btn-ghost btn-sm" style={{ color:'#7c3aed' }}>View All →</button>
              </div>
              <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fill,minmax(300px,1fr))', gap:16 }}>
                {[...upcomingExams, ...expiredExams]
                  .filter(e => applyFilters([e]).length > 0)
                  .map(e => <ExamCard key={e.exam_id} exam={e} />)}
              </div>
            </div>
          )}
        </>
      )}
    </div>
  );
};

export default AvailableExams;
